# The option that shuffles a category -> that category's locations. Its keys are the
# option attribute names, so gen, the item pool and slot data can all drive off it.
category_location_tables: dict[str, dict[str, LighthouseLocData]] = {
    "shuffle_beehive_honeycombs": beehive_honeycombs_location_table,
    "shuffle_blue_eggs": blue_eggs_location_table,
    "shuffle_empty_honeycombs": empty_honeycombs_location_table,
    "shuffle_extra_lives": extra_lives_location_table,
    "shuffle_jiggies": jiggies_location_table,
    "shuffle_jinjos": jinjos_location_table,
    "shuffle_molehills": molehills_location_table,
    "shuffle_mumbo_tokens": mumbo_tokens_location_table,
    "shuffle_music_notes": music_notes_location_table,
    "shuffle_stop_n_swop": stop_n_swop_location_table,
}

assert set(category_location_tables) == set(SHUFFLE_OPTIONS), \
    f"category_location_tables is out of sync with the shuffle options: " \
    f"{set(category_location_tables) ^ set(SHUFFLE_OPTIONS)}"


location_data_table: dict[str, LighthouseLocData] = {
    name: data for table in category_location_tables.values() for name, data in table.items()
}


location_table = {str(name): locdata.loc_id for name,
                  locdata in location_data_table.items()}
